import{_ as s,c as a,o as i,a2 as t}from"./chunks/framework.BQGPkCej.js";const b=JSON.parse('{"title":"手动部署","description":"","frontmatter":{},"headers":[],"relativePath":"deploy/install/manual.md","filePath":"deploy/install/manual.md","lastUpdated":1728809700000}'),e={name:"deploy/install/manual.md"},n=t(`<h1 id="手动部署" tabindex="-1">手动部署 <a class="header-anchor" href="#手动部署" aria-label="Permalink to &quot;手动部署&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>如果你希望在 Windows 中部署，<a href="./windows.html">这篇文章</a>可能是更好的选择</p></div><h2 id="前置" tabindex="-1">前置 <a class="header-anchor" href="#前置" aria-label="Permalink to &quot;前置&quot;">​</a></h2><p>首先你需要启动一个适配 OneBot v11 的实现端，例如<a href="https://docs.go-cqhttp.org/" target="_blank" rel="noreferrer">go-cqhttp</a>、<a href="https://github.com/lc-cn/onebots" target="_blank" rel="noreferrer">lc-cn/onebots</a>，更多的可在 <a href="https://onebot.dev/ecosystem.html#onebot-11-10-cqhttp" target="_blank" rel="noreferrer">OneBot 生态</a> 查看。</p><p>在实现端中开启 <strong>正向 websocket</strong>，配置 <strong>正向 websocket</strong> 服务地址。并检查是否正常启动了 <code>redis</code> 数据库。</p><h2 id="拉取项目源码" tabindex="-1">拉取项目源码 <a class="header-anchor" href="#拉取项目源码" aria-label="Permalink to &quot;拉取项目源码&quot;">​</a></h2><p>切换到你所希望存放 bot 的目录，拉取项目源码</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://mirror.ghproxy.com/https://github.com/SilveryStar/Adachi-BOT.git</span></span></code></pre></div><p>进入项目根目录，安装项目依赖</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Adachi-BOT</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div><h2 id="初始化" tabindex="-1">初始化 <a class="header-anchor" href="#初始化" aria-label="Permalink to &quot;初始化&quot;">​</a></h2><p>于根目录下执行命令来启动并初始化项目</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>在看到终端打印配置文件创建成功的提示后，项目根目录下将会生成一个 <code>config</code> 目录，这是 <code>Adachi-BOT</code> 的配置文件所在目录。</p><p>打开 <code>config/base.yml</code>，修改 <code>master</code> 为主人 qq 号码，并根据实现端所提供的<strong>正向 websocket 服务</strong>地址，按需填入 <code>wsServer</code> 与 <code>wsApiServer</code>。</p><p>一般情况下，其他配置文件内容无需修改。你同样可以参考 <a href="./../../config/base.html">配置项</a> 来酌情修改。</p><h2 id="启动项目" tabindex="-1">启动项目 <a class="header-anchor" href="#启动项目" aria-label="Permalink to &quot;启动项目&quot;">​</a></h2><p>再次于根目录下执行启动命令</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>一切正常的话，终端将会持续打印日志。并将在主人 qq 中收到 bot qq 发来的上线成功提醒。</p><h2 id="后台托管启动" tabindex="-1">后台托管启动 <a class="header-anchor" href="#后台托管启动" aria-label="Permalink to &quot;后台托管启动&quot;">​</a></h2><p>使用上述方式启动的项目，终端一经关闭 bot 服务则被停止。改为执行如下命令来实现后台托管启动</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> serve</span></span></code></pre></div><p>之后就可以安全将终端关闭，且不会影响 bot 的正常运行。 且此种启动方式允许使用 <strong>restart(重启)</strong>、<strong>upgrade(更新)</strong> 等快捷指令。</p><p>下面提供了几种在此模式下的帮助命令</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 查看终端日志</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pm2</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> log</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adachi-bot</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 重启项目 </span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> restart</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 停止项目</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span></span></code></pre></div>`,26),p=[n];function l(h,o,r,d,c,k){return i(),a("div",null,p)}const u=s(e,[["render",l]]);export{b as __pageData,u as default};
